import Foundation

/// The committed audio fixtures (#0195): one distinct sine per file, generated by `scripts/make-test-audio.sh`.
/// Frequencies: A 440, B 660, C 880, D 1100, E 1320, F 1760 Hz.
public enum AudioFixtures {
    public enum File: String, CaseIterable, Sendable {
        case toneAmp3 = "01 Tone A.mp3"
        case toneBmp3 = "02 Tone B.mp3"
        case toneCaac = "03 Tone C.m4a"
        case toneDalac = "04 Tone D.m4a"
        case toneEflac = "05 Tone E.flac"
        case toneFwav = "06 Tone F.wav"

        /// The sine's frequency.
        public var hz: Double {
            switch self {
            case .toneAmp3: 440
            case .toneBmp3: 660
            case .toneCaac: 880
            case .toneDalac: 1100
            case .toneEflac: 1320
            case .toneFwav: 1760
            }
        }

        /// The title the tags carry ("Tone A"); the WAV is untagged, so this is also its fallback title.
        public var title: String { "Tone " + String(rawValue.dropFirst(8).prefix(1)) }
    }

    public static let artist = "Tone Artist"
    public static let album = "Tone Album"

    /// The folder holding the files and `MANIFEST.txt`.
    public static var directory: URL {
        Bundle.module.url(forResource: "Audio", withExtension: nil)!
    }

    public static func url(_ file: File) -> URL { directory.appending(path: file.rawValue) }
    public static var all: [URL] { File.allCases.map(url) }
    public static var cover: URL { directory.appending(path: "cover.jpg") }

    /// One `MANIFEST.txt` row.
    public struct ManifestEntry: Sendable {
        public let name: String
        public let md5: String
        public let seconds: Double
        public let format: String
    }

    /// The manifest, keyed by file name.
    public static func manifest() throws -> [String: ManifestEntry] {
        let text = try String(contentsOf: directory.appending(path: "MANIFEST.txt"), encoding: .utf8)
        var entries: [String: ManifestEntry] = [:]
        for line in text.split(separator: "\n") where !line.hasPrefix("#") {
            let fields = line.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
            guard fields.count == 4, let seconds = Double(fields[2]) else { continue }
            entries[fields[0]] = ManifestEntry(name: fields[0], md5: fields[1], seconds: seconds, format: fields[3])
        }
        return entries
    }

    // MARK: Library

    /// What a folder index of `makeLibrary(at:)` should show.
    public struct ExpectedLibrary: Equatable, Sendable {
        public struct Album: Equatable, Sendable {
            public let artist: String
            public let title: String
            /// Track titles in index order (disc, then track number).
            public let tracks: [String]
            public let discs: [Int?]
        }

        public let artists: [String]
        public let albums: [Album]
        /// Every file written, relative to the root, sorted.
        public let files: [String]
        public let playlist: String
    }

    /// The layout, as (relative path, source). `scripts/make-test-library.sh` writes the same tree;
    /// `makeLibraryMatchesTheScript` keeps the two in step.
    static let layout: [(path: String, source: String)] = [
        ("Tone Artist/Tone Album/01 Tone A.mp3", File.toneAmp3.rawValue),
        ("Tone Artist/Tone Album/02 Tone B.mp3", File.toneBmp3.rawValue),
        ("Tone Artist/Tone Album/03 Tone C.m4a", File.toneCaac.rawValue),
        ("Tone Artist/Tone Album/cover.jpg", "cover.jpg"),
        ("Tone Artist/Two Discs/Disc 1/04 Tone D.m4a", File.toneDalac.rawValue),
        ("Tone Artist/Two Discs/Disc 1/05 Tone E.flac", File.toneEflac.rawValue),
        ("Tone Artist/Two Discs/Disc 2/06 Tone F.wav", File.toneFwav.rawValue),
        ("Other Artist/Single.m4a", File.toneCaac.rawValue),
    ]

    public static let playlistName = "Party.m3u"
    public static let playlistText = """
        #EXTM3U
        Tone Artist/Tone Album/01 Tone A.mp3
        Tone Artist/Two Discs/Disc 2/06 Tone F.wav
        Other Artist/Single.m4a

        """

    /// Copies the files into `root` as Artist/Album/Track (two artists, three albums, a two-disc album,
    /// one single in the artist folder, one M3U) and returns the expected listing.
    @discardableResult
    public static func makeLibrary(at root: URL) throws -> ExpectedLibrary {
        let fm = FileManager.default
        for entry in layout {
            let target = root.appending(path: entry.path)
            try fm.createDirectory(at: target.deletingLastPathComponent(), withIntermediateDirectories: true)
            try fm.copyItem(at: directory.appending(path: entry.source), to: target)
        }
        try Data(playlistText.utf8).write(to: root.appending(path: playlistName))
        return ExpectedLibrary(
            artists: ["Other Artist", "Tone Artist"],
            albums: [
                .init(artist: "Tone Artist", title: "Tone Album", tracks: ["Tone A", "Tone B", "Tone C"], discs: [nil, nil, nil]),
                // The FLAC's Vorbis comments aren't in AVFoundation's common metadata, so its title comes from the file name.
                .init(artist: "Tone Artist", title: "Two Discs", tracks: ["Tone D", "Tone E", "Tone F"], discs: [1, 1, 2]),
                // The single is a copy of the AAC file, so it carries Tone C's tags.
                .init(artist: "Other Artist", title: "Singles", tracks: ["Tone C"], discs: [nil]),
            ],
            files: (layout.map(\.path) + [playlistName]).sorted(),
            playlist: playlistName)
    }
}
